const items = [];
for (const item of $input.all()) {
  const binaryKeys = Object.keys(item.binary || {});
  for (const key of binaryKeys) {
    const bin = item.binary[key];
    if (bin.mimeType === 'application/pdf') {
      items.push({
        json: { emailId: item.json.id, emailSubject: item.json.subject, emailDate: item.json.date, fileName: bin.fileName || key, mimeType: bin.mimeType },
        binary: { data: bin }
      });
    }
  }
}
return items;

const filterItems = $('Filter PDF Attachments').all();

return $input.all().map((item, i) => {
  const raw = item.json.output;
  const parsed = JSON.parse(raw);
  const emailId = filterItems[i]?.json?.emailId || null;

  // banco siempre Macro
  parsed.resumen.banco = 'Macro';

  // normalizar titular
  parsed.resumen.titular = parsed.resumen.titular
    .split(',')
    .map(p => p.trim().toLowerCase().replace(/\b\w/g, c => c.toUpperCase()))
    .join(', ');

  // nro_socio: solo dígitos; fallback al nro conocido si el AI no lo extrajo
  parsed.resumen.nro_socio = (parsed.resumen.nro_socio || '').replace(/[^\d]/g, '') || '1377397111';

  // validar fechas: reemplazar fechas inválidas con null
  const validDate = d => (d && d !== '0000-00-00' && /^\d{4}-\d{2}-\d{2}$/.test(d)) ? d : null;
  parsed.resumen.cierre_actual = validDate(parsed.resumen.cierre_actual);
  parsed.resumen.vencimiento_actual = validDate(parsed.resumen.vencimiento_actual);

  // nro_resumen: limpiar espacios y prefixear con MACRO-{cuenta}
  if (parsed.resumen.nro_resumen) {
    const cleaned = parsed.resumen.nro_resumen.replace(/\s*-\s*/g, '-').replace(/\s+/g, '-').trim();
    parsed.resumen.nro_resumen = `MACRO-${parsed.resumen.nro_socio}-${cleaned}`;
  } else {
    parsed.resumen.nro_resumen = `NONUM-${parsed.resumen.nro_socio}-${parsed.resumen.cierre_actual}`;
  }

  // limpiar consumos
  parsed.consumos = parsed.consumos.map(c => ({
    ...c,
    referencia: c.referencia.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1').trim(),
    comprobante: c.comprobante.trim().split(/\s+/).pop()
  }));

  return { json: { emailId, resumen: parsed.resumen, consumos: parsed.consumos } };
});

const tarjeta = $input.first().json;
const jsonParseItems = $('JSON Parse').all();

return jsonParseItems.map(item => ({
  json: { ...item.json, tarjeta_id: tarjeta.id || null }
}));

const resumenes = $input.all();
const jsonParseItems = $('JSON Parse').all();

return resumenes.map((item, i) => {
  const resumenId = item.json.id || null;
  const emailId = jsonParseItems[i]?.json?.emailId || null;
  const consumos = resumenId ? (jsonParseItems[i]?.json?.consumos || []) : [];
  return { json: { ...item.json, id: resumenId, consumos, emailId } };
});

const items = [];
for (const item of $input.all()) {
  const resumenId = item.json.id;
  const nro_resumen = item.json.nro_resumen;
  const consumos = item.json.consumos;
  if (!consumos) continue;
  for (const c of consumos) {
    items.push({
      json: {
        resumen_id: resumenId, nro_resumen, fecha: c.fecha, referencia: c.referencia,
        comprobante: c.comprobante, pesos: c.pesos, dolares: c.dolares,
        adicional: c.adicional, cuota_actual: c.cuota_actual ?? null, cantidad_cuotas: c.cantidad_cuotas ?? null
      },
      pairedItem: { item: $input.all().indexOf(item) }
    });
  }
}
return items;

const mergeItems = $('Merge Consumos').all();
const emailIds = [...new Set(mergeItems.map(i => i.json.emailId))];
return emailIds.map(emailId => ({ json: { emailId } }));
